-- DevArena core schema. All identifiers are UUIDs generated by the application.

CREATE TABLE users (
    id              UUID PRIMARY KEY,
    email           VARCHAR(254) NOT NULL,
    username        VARCHAR(32)  NOT NULL,
    password_hash   VARCHAR(100) NOT NULL,
    display_name    VARCHAR(60)  NOT NULL,
    avatar_url      VARCHAR(500),
    bio             VARCHAR(500),
    role            VARCHAR(20)  NOT NULL DEFAULT 'USER' CHECK (role IN ('USER', 'ADMIN')),
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX ux_users_email ON users (lower(email));
CREATE UNIQUE INDEX ux_users_username ON users (lower(username));

CREATE TABLE user_settings (
    user_id                 UUID PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    preferred_language      VARCHAR(20)  NOT NULL DEFAULT 'JAVA',
    target_role             VARCHAR(40)  NOT NULL DEFAULT 'BACKEND_ENGINEER',
    prep_level              VARCHAR(20)  NOT NULL DEFAULT 'INTERMEDIATE',
    daily_study_minutes     INT          NOT NULL DEFAULT 60 CHECK (daily_study_minutes BETWEEN 15 AND 480),
    daily_mission_minimum   INT          NOT NULL DEFAULT 2 CHECK (daily_mission_minimum BETWEEN 1 AND 7),
    time_zone               VARCHAR(64)  NOT NULL DEFAULT 'UTC',
    roadmap_start_date      DATE         NOT NULL,
    onboarded               BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at              TIMESTAMPTZ  NOT NULL,
    updated_at              TIMESTAMPTZ  NOT NULL
);

CREATE TABLE friendships (
    id              UUID PRIMARY KEY,
    requester_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    addressee_id    UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    status          VARCHAR(20) NOT NULL CHECK (status IN ('PENDING', 'ACCEPTED')),
    created_at      TIMESTAMPTZ NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL,
    CHECK (requester_id <> addressee_id)
);
-- One relationship per unordered pair of users.
CREATE UNIQUE INDEX ux_friendships_pair ON friendships (LEAST(requester_id, addressee_id), GREATEST(requester_id, addressee_id));
CREATE INDEX ix_friendships_addressee ON friendships (addressee_id, status);

-- ---------------------------------------------------------------- content

CREATE TABLE topics (
    id          UUID PRIMARY KEY,
    slug        VARCHAR(60)  NOT NULL UNIQUE,
    name        VARCHAR(80)  NOT NULL,
    category    VARCHAR(30)  NOT NULL,
    description VARCHAR(400),
    sort_order  INT          NOT NULL DEFAULT 0
);
CREATE INDEX ix_topics_category ON topics (category, sort_order);

CREATE TABLE questions (
    id              UUID PRIMARY KEY,
    slug            VARCHAR(100) NOT NULL UNIQUE,
    topic_id        UUID         NOT NULL REFERENCES topics (id),
    difficulty      VARCHAR(10)  NOT NULL CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')),
    prompt          TEXT         NOT NULL,
    code_snippet    TEXT,
    explanation     TEXT         NOT NULL,
    status          VARCHAR(10)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DRAFT', 'ARCHIVED')),
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL DEFAULT 0
);
CREATE INDEX ix_questions_topic ON questions (topic_id, difficulty) WHERE status = 'ACTIVE';

CREATE TABLE question_options (
    id          UUID PRIMARY KEY,
    question_id UUID         NOT NULL REFERENCES questions (id) ON DELETE CASCADE,
    position    INT          NOT NULL,
    body        VARCHAR(600) NOT NULL,
    correct     BOOLEAN      NOT NULL,
    UNIQUE (question_id, position)
);
-- Exactly one correct option per question.
CREATE UNIQUE INDEX ux_question_options_one_correct ON question_options (question_id) WHERE correct;

CREATE TABLE question_attempts (
    id                  UUID PRIMARY KEY,
    user_id             UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    question_id         UUID        NOT NULL REFERENCES questions (id),
    selected_option_id  UUID        REFERENCES question_options (id),
    correct             BOOLEAN     NOT NULL,
    context             VARCHAR(20) NOT NULL CHECK (context IN ('PRACTICE', 'MISSION', 'BATTLE')),
    context_id          UUID,
    created_at          TIMESTAMPTZ NOT NULL
);
CREATE INDEX ix_attempts_user_time ON question_attempts (user_id, created_at DESC);
CREATE INDEX ix_attempts_user_question ON question_attempts (user_id, question_id, created_at DESC);

CREATE TABLE bookmarks (
    user_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    question_id UUID        NOT NULL REFERENCES questions (id) ON DELETE CASCADE,
    created_at  TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (user_id, question_id)
);

CREATE TABLE coding_problems (
    id                UUID PRIMARY KEY,
    slug              VARCHAR(100) NOT NULL UNIQUE,
    title             VARCHAR(140) NOT NULL,
    topic_id          UUID         NOT NULL REFERENCES topics (id),
    difficulty        VARCHAR(10)  NOT NULL CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')),
    statement         TEXT         NOT NULL,
    examples          TEXT         NOT NULL,
    constraints_text  TEXT         NOT NULL,
    starter_code      TEXT         NOT NULL,
    -- Interviewer-only material. Never serialised to candidates.
    solution_outline  TEXT         NOT NULL,
    created_at        TIMESTAMPTZ  NOT NULL,
    updated_at        TIMESTAMPTZ  NOT NULL
);

CREATE TABLE design_problems (
    id                      UUID PRIMARY KEY,
    slug                    VARCHAR(100) NOT NULL UNIQUE,
    title                   VARCHAR(140) NOT NULL,
    difficulty              VARCHAR(10)  NOT NULL CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')),
    summary                 TEXT         NOT NULL,
    functional_reqs         TEXT[]       NOT NULL,
    non_functional_reqs     TEXT[]       NOT NULL,
    -- Interviewer-only material.
    discussion_topics       TEXT[]       NOT NULL,
    follow_ups              TEXT[]       NOT NULL,
    created_at              TIMESTAMPTZ  NOT NULL,
    updated_at              TIMESTAMPTZ  NOT NULL
);

CREATE TABLE interview_questions (
    id                  UUID PRIMARY KEY,
    slug                VARCHAR(100) NOT NULL UNIQUE,
    interview_type      VARCHAR(30)  NOT NULL,
    difficulty          VARCHAR(10)  NOT NULL CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')),
    title               VARCHAR(140) NOT NULL,
    prompt              TEXT         NOT NULL,
    coding_problem_id   UUID REFERENCES coding_problems (id),
    design_problem_id   UUID REFERENCES design_problems (id),
    -- Interviewer-only guide.
    expected_concepts   TEXT[]       NOT NULL,
    answer_outline      TEXT         NOT NULL,
    common_mistakes     TEXT[]       NOT NULL,
    follow_ups          TEXT[]       NOT NULL,
    rubric_notes        TEXT         NOT NULL,
    created_at          TIMESTAMPTZ  NOT NULL,
    updated_at          TIMESTAMPTZ  NOT NULL
);
CREATE INDEX ix_interview_questions_type ON interview_questions (interview_type, difficulty);

CREATE TABLE content_seed_log (
    name        VARCHAR(100) PRIMARY KEY,
    checksum    VARCHAR(64)  NOT NULL,
    applied_at  TIMESTAMPTZ  NOT NULL
);

-- ---------------------------------------------------------------- missions & progress

CREATE TABLE mission_assignments (
    id                  UUID PRIMARY KEY,
    user_id             UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    assigned_date       DATE        NOT NULL,
    roadmap_day         INT         NOT NULL CHECK (roadmap_day BETWEEN 1 AND 90),
    slot                INT         NOT NULL,
    mission_type        VARCHAR(20) NOT NULL CHECK (mission_type IN ('QUESTION_SET', 'INTERVIEW_STUDY', 'DESIGN_STUDY')),
    category            VARCHAR(30) NOT NULL,
    topic_id            UUID REFERENCES topics (id),
    title               VARCHAR(140) NOT NULL,
    difficulty          VARCHAR(10) NOT NULL,
    estimated_minutes   INT         NOT NULL,
    xp_reward           INT         NOT NULL,
    is_revision         BOOLEAN     NOT NULL DEFAULT FALSE,
    payload             JSONB       NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL,
    UNIQUE (user_id, assigned_date, slot)
);

CREATE TABLE mission_completions (
    id              UUID PRIMARY KEY,
    assignment_id   UUID        NOT NULL UNIQUE REFERENCES mission_assignments (id) ON DELETE CASCADE,
    user_id         UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    correct_count   INT         NOT NULL DEFAULT 0,
    total_count     INT         NOT NULL DEFAULT 0,
    response        JSONB,
    completed_at    TIMESTAMPTZ NOT NULL
);
CREATE INDEX ix_mission_completions_user ON mission_completions (user_id, completed_at DESC);

CREATE TABLE skill_progress (
    user_id             UUID          NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    topic_id            UUID          NOT NULL REFERENCES topics (id),
    attempts            INT           NOT NULL,
    correct             INT           NOT NULL,
    mastery             NUMERIC(5, 4) NOT NULL,
    last_practiced_at   TIMESTAMPTZ   NOT NULL,
    updated_at          TIMESTAMPTZ   NOT NULL,
    PRIMARY KEY (user_id, topic_id)
);

CREATE TABLE xp_transactions (
    id          UUID PRIMARY KEY,
    user_id     UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    amount      INT          NOT NULL CHECK (amount > 0),
    source_type VARCHAR(30)  NOT NULL,
    source_id   VARCHAR(80)  NOT NULL,
    reason      VARCHAR(140) NOT NULL,
    created_at  TIMESTAMPTZ  NOT NULL,
    -- The database itself refuses a second award for the same source.
    UNIQUE (user_id, source_type, source_id)
);
CREATE INDEX ix_xp_user_time ON xp_transactions (user_id, created_at DESC);
CREATE INDEX ix_xp_time ON xp_transactions (created_at DESC);

CREATE TABLE daily_activity (
    user_id             UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    activity_date       DATE NOT NULL,
    xp_earned           INT  NOT NULL DEFAULT 0,
    missions_completed  INT  NOT NULL DEFAULT 0,
    questions_answered  INT  NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, activity_date)
);

CREATE TABLE achievements (
    id              UUID PRIMARY KEY,
    code            VARCHAR(40)  NOT NULL UNIQUE,
    name            VARCHAR(60)  NOT NULL,
    description     VARCHAR(200) NOT NULL,
    icon            VARCHAR(40)  NOT NULL,
    criteria_type   VARCHAR(30)  NOT NULL,
    threshold       INT          NOT NULL
);

CREATE TABLE user_achievements (
    user_id         UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    achievement_id  UUID        NOT NULL REFERENCES achievements (id),
    unlocked_at     TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (user_id, achievement_id)
);

-- ---------------------------------------------------------------- quiz battles

CREATE TABLE quiz_battles (
    id                      UUID PRIMARY KEY,
    room_code               VARCHAR(8)  NOT NULL UNIQUE,
    host_id                 UUID        NOT NULL REFERENCES users (id),
    category                VARCHAR(30) NOT NULL,
    difficulty              VARCHAR(10) NOT NULL,
    question_count          INT         NOT NULL CHECK (question_count BETWEEN 3 AND 20),
    seconds_per_question    INT         NOT NULL CHECK (seconds_per_question BETWEEN 10 AND 120),
    status                  VARCHAR(20) NOT NULL CHECK (status IN ('WAITING', 'READY', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED')),
    current_index           INT         NOT NULL DEFAULT -1,
    started_at              TIMESTAMPTZ,
    ended_at                TIMESTAMPTZ,
    winner_id               UUID REFERENCES users (id),
    created_at              TIMESTAMPTZ NOT NULL,
    updated_at              TIMESTAMPTZ NOT NULL,
    version                 BIGINT      NOT NULL DEFAULT 0
);
CREATE INDEX ix_quiz_battles_status ON quiz_battles (status);

CREATE TABLE quiz_battle_participants (
    id              UUID PRIMARY KEY,
    battle_id       UUID        NOT NULL REFERENCES quiz_battles (id) ON DELETE CASCADE,
    user_id         UUID        NOT NULL REFERENCES users (id),
    ready           BOOLEAN     NOT NULL DEFAULT FALSE,
    score           INT         NOT NULL DEFAULT 0,
    correct_count   INT         NOT NULL DEFAULT 0,
    joined_at       TIMESTAMPTZ NOT NULL,
    UNIQUE (battle_id, user_id)
);
CREATE INDEX ix_battle_participants_user ON quiz_battle_participants (user_id);

CREATE TABLE quiz_battle_questions (
    id          UUID PRIMARY KEY,
    battle_id   UUID        NOT NULL REFERENCES quiz_battles (id) ON DELETE CASCADE,
    question_id UUID        NOT NULL REFERENCES questions (id),
    position    INT         NOT NULL,
    started_at  TIMESTAMPTZ,
    ends_at     TIMESTAMPTZ,
    UNIQUE (battle_id, position),
    UNIQUE (battle_id, question_id)
);

CREATE TABLE quiz_answers (
    id                  UUID PRIMARY KEY,
    battle_question_id  UUID        NOT NULL REFERENCES quiz_battle_questions (id) ON DELETE CASCADE,
    user_id             UUID        NOT NULL REFERENCES users (id),
    option_id           UUID        REFERENCES question_options (id),
    correct             BOOLEAN     NOT NULL,
    points              INT         NOT NULL,
    response_ms         INT         NOT NULL,
    answered_at         TIMESTAMPTZ NOT NULL,
    -- One answer per player per question, enforced by the database.
    UNIQUE (battle_question_id, user_id)
);

-- ---------------------------------------------------------------- interviews

CREATE TABLE interview_sessions (
    id                  UUID PRIMARY KEY,
    room_code           VARCHAR(12) NOT NULL UNIQUE,
    interview_type      VARCHAR(30) NOT NULL,
    difficulty          VARCHAR(10) NOT NULL,
    duration_minutes    INT         NOT NULL CHECK (duration_minutes BETWEEN 10 AND 120),
    status              VARCHAR(20) NOT NULL CHECK (status IN ('CREATED', 'LOBBY', 'ACTIVE', 'FEEDBACK', 'COMPLETED', 'CANCELLED')),
    interviewer_id      UUID        NOT NULL REFERENCES users (id),
    candidate_id        UUID REFERENCES users (id),
    current_index       INT         NOT NULL DEFAULT 0,
    started_at          TIMESTAMPTZ,
    ended_at            TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    version             BIGINT      NOT NULL DEFAULT 0,
    CHECK (candidate_id IS NULL OR candidate_id <> interviewer_id)
);
CREATE INDEX ix_interviews_interviewer ON interview_sessions (interviewer_id, created_at DESC);
CREATE INDEX ix_interviews_candidate ON interview_sessions (candidate_id, created_at DESC);

CREATE TABLE interview_session_questions (
    id                      UUID PRIMARY KEY,
    session_id              UUID        NOT NULL REFERENCES interview_sessions (id) ON DELETE CASCADE,
    interview_question_id   UUID        NOT NULL REFERENCES interview_questions (id),
    position                INT         NOT NULL,
    asked_at                TIMESTAMPTZ,
    UNIQUE (session_id, position)
);

CREATE TABLE interview_evaluations (
    id                  UUID PRIMARY KEY,
    session_id          UUID         NOT NULL UNIQUE REFERENCES interview_sessions (id) ON DELETE CASCADE,
    evaluator_id        UUID         NOT NULL REFERENCES users (id),
    technical           INT          NOT NULL CHECK (technical BETWEEN 1 AND 5),
    depth               INT          NOT NULL CHECK (depth BETWEEN 1 AND 5),
    problem_solving     INT          NOT NULL CHECK (problem_solving BETWEEN 1 AND 5),
    communication       INT          NOT NULL CHECK (communication BETWEEN 1 AND 5),
    follow_up_handling  INT          NOT NULL CHECK (follow_up_handling BETWEEN 1 AND 5),
    overall             NUMERIC(3, 2) NOT NULL,
    strengths           TEXT         NOT NULL,
    improvements        TEXT         NOT NULL,
    summary             TEXT,
    created_at          TIMESTAMPTZ  NOT NULL
);

-- Private interviewer notes: only ever returned to their author.
CREATE TABLE interview_notes (
    id                  UUID PRIMARY KEY,
    session_id          UUID        NOT NULL REFERENCES interview_sessions (id) ON DELETE CASCADE,
    author_id           UUID        NOT NULL REFERENCES users (id),
    session_question_id UUID REFERENCES interview_session_questions (id) ON DELETE CASCADE,
    body                TEXT        NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL,
    updated_at          TIMESTAMPTZ NOT NULL,
    UNIQUE (session_id, author_id, session_question_id)
);

-- ---------------------------------------------------------------- code & design work

CREATE TABLE code_submissions (
    id                      UUID PRIMARY KEY,
    user_id                 UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    problem_id              UUID REFERENCES coding_problems (id),
    interview_session_id    UUID REFERENCES interview_sessions (id) ON DELETE CASCADE,
    language                VARCHAR(20) NOT NULL,
    code                    TEXT        NOT NULL,
    note                    VARCHAR(500),
    created_at              TIMESTAMPTZ NOT NULL
);
CREATE INDEX ix_code_submissions_user ON code_submissions (user_id, created_at DESC);
CREATE INDEX ix_code_submissions_session ON code_submissions (interview_session_id, created_at DESC);

CREATE TABLE design_documents (
    id                      UUID PRIMARY KEY,
    user_id                 UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    problem_id              UUID        NOT NULL REFERENCES design_problems (id),
    interview_session_id    UUID REFERENCES interview_sessions (id) ON DELETE CASCADE,
    diagram                 JSONB       NOT NULL,
    notes                   TEXT        NOT NULL DEFAULT '',
    submitted_at            TIMESTAMPTZ,
    created_at              TIMESTAMPTZ NOT NULL,
    updated_at              TIMESTAMPTZ NOT NULL,
    version                 BIGINT      NOT NULL DEFAULT 0
);
CREATE INDEX ix_design_documents_user ON design_documents (user_id, updated_at DESC);
